"""Generated solver store — stores SymPy solver code generated by DeepSeek.

When DeepSeek encounters a question type SymPy can't handle:
1. DeepSeek solves the question (for the student now)
2. DeepSeek writes a SymPy function that can solve this PATTERN
3. We store: pattern → solver code
4. Next time same pattern → exec the stored solver with new values → no DeepSeek

The system becomes self-improving: every new question type only needs
ONE DeepSeek call. After that, SymPy handles it forever.
"""
from __future__ import annotations

import json
import logging
import numpy as np
from datetime import datetime
from pathlib import Path
from typing import Optional, Any

from backend.ai.pattern_store import normalize_question

logger = logging.getLogger(__name__)

STORE_FILE = Path(__file__).parent / "_generated_solvers.json"
EMBEDDINGS_FILE = Path(__file__).parent / "_solver_embeddings.npy"


class GeneratedSolverStore:
    """Stores SymPy solver code generated by DeepSeek, keyed by pattern."""

    def __init__(self):
        self._solvers: list[dict] = []
        self._embeddings: Optional[np.ndarray] = None
        self._embedder = None
        self._compiled: dict[str, Any] = {}  # pattern → compiled function

    def _load_embedder(self):
        if self._embedder is None:
            import os
            os.environ['TRANSFORMERS_OFFLINE'] = '1'
            os.environ['HF_HUB_OFFLINE'] = '1'
            from sentence_transformers import SentenceTransformer
            self._embedder = SentenceTransformer('all-MiniLM-L6-v2')
        return self._embedder

    def load(self) -> None:
        if self._solvers:
            return
        if STORE_FILE.exists():
            try:
                self._solvers = json.loads(STORE_FILE.read_text(encoding="utf-8"))
                logger.info(f"Loaded {len(self._solvers)} generated solvers")
            except Exception as e:
                logger.warning(f"Failed to load solvers: {e}")
                self._solvers = []
        if EMBEDDINGS_FILE.exists():
            self._embeddings = np.load(EMBEDDINGS_FILE)
        else:
            self._embeddings = None

    def save(self) -> None:
        STORE_FILE.write_text(
            json.dumps(self._solvers, indent=2, ensure_ascii=False),
            encoding="utf-8"
        )
        if self._embeddings is not None:
            np.save(EMBEDDINGS_FILE, self._embeddings)

    def add(self, question: str, solver_code: str, category: str,
            form_fields: list[dict], example_solution: str) -> None:
        """Store a generated solver for a pattern."""
        self.load()
        pattern = normalize_question(question)

        # Don't store duplicates
        for s in self._solvers:
            if s["pattern"] == pattern:
                return

        embedder = self._load_embedder()
        p_emb = embedder.encode([pattern], normalize_embeddings=True)[0]

        entry = {
            "pattern": pattern,
            "original_question": question[:500],
            "category": category,
            "form_fields": form_fields,
            "solver_code": solver_code,
            "example_solution": example_solution,
            "created_at": datetime.now().isoformat(),
            "embedding": p_emb.tolist(),
        }
        self._solvers.append(entry)

        if self._embeddings is None:
            self._embeddings = np.array([p_emb])
        else:
            self._embeddings = np.vstack([self._embeddings, p_emb])

        self.save()
        logger.info(f"Stored generated solver for pattern: '{pattern[:60]}...' (total: {len(self._solvers)})")

    def match(self, question: str, threshold: float = 0.85) -> Optional[dict]:
        """Find a stored solver for this question pattern.
        
        Uses exact normalized string matching only — no embeddings.
        """
        self.load()
        if not self._solvers:
            return None

        pattern = normalize_question(question)

        # Exact pattern match only
        for s in self._solvers:
            if s["pattern"] == pattern:
                return s
        return None

    def get_solver_fn(self, pattern: str) -> Optional[Any]:
        """Get a compiled solver function for a pattern."""
        if pattern in self._compiled:
            return self._compiled[pattern]

        # Find the solver entry
        for s in self._solvers:
            if s["pattern"] == pattern:
                try:
                    # Compile the solver code
                    # The code should define a function called `solve(values: dict) -> dict`
                    local_ns: dict = {}
                    exec(s["solver_code"], local_ns)
                    fn = local_ns.get("solve")
                    if fn:
                        self._compiled[pattern] = fn
                        return fn
                except Exception as e:
                    logger.warning(f"Failed to compile solver for pattern: {e}")
                return None
        return None

    def count(self) -> int:
        self.load()
        return len(self._solvers)


# Singleton
_store: Optional[GeneratedSolverStore] = None


def get_solver_store() -> GeneratedSolverStore:
    global _store
    if _store is None:
        _store = GeneratedSolverStore()
        _store.load()
    return _store
